// packages/engine/Specs/Core/RectangleCollisionCheckerSpec.js
var import_core208 = __toESM(require_Cesium(), 1);
var import__308 = __toESM(require_Cesium(), 1);
describe("Core/RectangleCollisionChecker", function() {
  const testRectangle1 = new import_core208.Rectangle(0, 0, 1, 1);
  const testRectangle2 = new import_core208.Rectangle(1.1, 1.1, 2.1, 2.1);
  const testRectangle3 = new import_core208.Rectangle(1.1, 1.1, 1.2, 1.2);
  it("Checks for collisions with contained rectangles", function() {
    const collisionChecker = new import__308.RectangleCollisionChecker();
    collisionChecker.insert("test1", testRectangle1);
    expect(collisionChecker.collides(testRectangle2)).toBe(false);
    collisionChecker.insert("test3", testRectangle3);
    expect(collisionChecker.collides(testRectangle2)).toBe(true);
  });
  it("removes rectangles", function() {
    const collisionChecker = new import__308.RectangleCollisionChecker();
    collisionChecker.insert("test1", testRectangle1);
    collisionChecker.insert("test3", testRectangle3);
    expect(collisionChecker.collides(testRectangle2)).toBe(true);
    collisionChecker.remove("test3", testRectangle3);
    expect(collisionChecker.collides(testRectangle2)).toBe(false);
  });
});

